00145 void InitCallstack()
00146 {
00147     _SymAddrIncludeInlineTrace = (t_SymAddrIncludeInlineTrace)GetProcAddress( GetModuleHandleA( "dbghelp.dll" ), "SymAddrIncludeInlineTrace" );
00148     _SymQueryInlineTrace = (t_SymQueryInlineTrace)GetProcAddress( GetModuleHandleA( "dbghelp.dll" ), "SymQueryInlineTrace" );
00149     _SymFromInlineContext = (t_SymFromInlineContext)GetProcAddress( GetModuleHandleA( "dbghelp.dll" ), "SymFromInlineContext" );
00150     _SymGetLineFromInlineContext = (t_SymGetLineFromInlineContext)GetProcAddress( GetModuleHandleA( "dbghelp.dll" ), "SymGetLineFromInlineContext" );
00151 
00152 #ifdef TRACY_DBGHELP_LOCK
00153     DBGHELP_INIT;
00154     DBGHELP_LOCK;
00155 #endif
00156 
00157     SymInitialize( GetCurrentProcess(), nullptr, true );
00158     SymSetOptions( SYMOPT_LOAD_LINES );
00159 
00160     DWORD needed;
00161     LPVOID dev[4096];
00162     if( EnumDeviceDrivers( dev, sizeof(dev), &needed ) != 0 )
00163     {
00164         char windir[MAX_PATH];
00165         if( !GetWindowsDirectoryA( windir, sizeof( windir ) ) ) memcpy( windir, "c:\\windows", 11 );
00166         const auto windirlen = strlen( windir );
00167 
00168         const auto sz = needed / sizeof( LPVOID );
00169         s_krnlCache = (KernelDriver*)tracy_malloc( sizeof(KernelDriver) * sz );
00170         int cnt = 0;
00171         for( size_t i=0; i<sz; i++ )
00172         {
00173             char fn[MAX_PATH];
00174             const auto len = GetDeviceDriverBaseNameA( dev[i], fn, sizeof( fn ) );
00175             if( len != 0 )
00176             {
00177                 auto buf = (char*)tracy_malloc_fast( len+3 );
00178                 buf[0] = '<';
00179                 memcpy( buf+1, fn, len );
00180                 memcpy( buf+len+1, ">", 2 );
00181                 s_krnlCache[cnt] = KernelDriver { (uint64_t)dev[i], buf };
00182 
00183                 const auto len = GetDeviceDriverFileNameA( dev[i], fn, sizeof( fn ) );
00184                 if( len != 0 )
00185                 {
00186                     char full[MAX_PATH];
00187                     char* path = fn;
00188 
00189                     if( memcmp( fn, "\\SystemRoot\\", 12 ) == 0 )
00190                     {
00191                         memcpy( full, windir, windirlen );
00192                         strcpy( full + windirlen, fn + 11 );
00193                         path = full;
00194                     }
00195 
00196                     SymLoadModuleEx( GetCurrentProcess(), nullptr, path, nullptr, (DWORD64)dev[i], 0, nullptr, 0 );
00197 
00198                     const auto psz = strlen( path );
00199                     auto pptr = (char*)tracy_malloc_fast( psz+1 );
00200                     memcpy( pptr, path, psz );
00201                     pptr[psz] = '\0';
00202                     s_krnlCache[cnt].path = pptr;
00203                 }
00204 
00205                 cnt++;
00206             }
00207         }
00208         s_krnlCacheCnt = cnt;
00209         std::sort( s_krnlCache, s_krnlCache + s_krnlCacheCnt, []( const KernelDriver& lhs, const KernelDriver& rhs ) { return lhs.addr > rhs.addr; } );
00210     }
00211 
00212     s_modCache = (FastVector<ModuleCache>*)tracy_malloc( sizeof( FastVector<ModuleCache> ) );
00213     new(s_modCache) FastVector<ModuleCache>( 512 );
00214 
00215     HANDLE proc = GetCurrentProcess();
00216     HMODULE mod[1024];
00217     if( EnumProcessModules( proc, mod, sizeof( mod ), &needed ) != 0 )
00218     {
00219         const auto sz = needed / sizeof( HMODULE );
00220         for( size_t i=0; i<sz; i++ )
00221         {
00222             MODULEINFO info;
00223             if( GetModuleInformation( proc, mod[i], &info, sizeof( info ) ) != 0 )
00224             {
00225                 const auto base = uint64_t( info.lpBaseOfDll );
00226                 char name[1024];
00227                 const auto res = GetModuleFileNameA( mod[i], name, 1021 );
00228                 if( res > 0 )
00229                 {
00230                     // This may be a new module loaded since our call to SymInitialize.
00231                     // Just in case, force DbgHelp to load its pdb !
00232                     SymLoadModuleEx(proc, NULL, name, NULL, (DWORD64)info.lpBaseOfDll, info.SizeOfImage, NULL, 0);
00233 
00234                     auto ptr = name + res;
00235                     while( ptr > name && *ptr != '\\' && *ptr != '/' ) ptr--;
00236                     if( ptr > name ) ptr++;
00237                     const auto namelen = name + res - ptr;
00238                     auto cache = s_modCache->push_next();
00239                     cache->start = base;
00240                     cache->end = base + info.SizeOfImage;
00241                     cache->name = (char*)tracy_malloc_fast( namelen+3 );
00242                     cache->name[0] = '[';
00243                     memcpy( cache->name+1, ptr, namelen );
00244                     cache->name[namelen+1] = ']';
00245                     cache->name[namelen+2] = '\0';
00246                 }
00247             }
00248         }
00249     }
00250 
00251 #ifdef TRACY_DBGHELP_LOCK
00252     DBGHELP_UNLOCK;
00253 #endif
00254 }
