00288 const char* GetKernelModulePath( uint64_t addr )
00289 {
00290     assert( addr >> 63 != 0 );
00291     if( !s_krnlCache ) return nullptr;
00292     auto it = std::lower_bound( s_krnlCache, s_krnlCache + s_krnlCacheCnt, addr, []( const KernelDriver& lhs, const uint64_t& rhs ) { return lhs.addr > rhs; } );
00293     if( it == s_krnlCache + s_krnlCacheCnt ) return nullptr;
00294     return it->path;
00295 }
