00297 static const char* GetModuleNameAndPrepareSymbols( uint64_t addr )
00298 {
00299     if( ( addr >> 63 ) != 0 )
00300     {
00301         if( s_krnlCache )
00302         {
00303             auto it = std::lower_bound( s_krnlCache, s_krnlCache + s_krnlCacheCnt, addr, []( const KernelDriver& lhs, const uint64_t& rhs ) { return lhs.addr > rhs; } );
00304             if( it != s_krnlCache + s_krnlCacheCnt )
00305             {
00306                 return it->mod;
00307             }
00308         }
00309         return "<kernel>";
00310     }
00311 
00312     for( auto& v : *s_modCache )
00313     {
00314         if( addr >= v.start && addr < v.end )
00315         {
00316             return v.name;
00317         }
00318     }
00319 
00320     HMODULE mod[1024];
00321     DWORD needed;
00322     HANDLE proc = GetCurrentProcess();
00323 
00324     InitRpmalloc();
00325     if( EnumProcessModules( proc, mod, sizeof( mod ), &needed ) != 0 )
00326     {
00327         const auto sz = needed / sizeof( HMODULE );
00328         for( size_t i=0; i<sz; i++ )
00329         {
00330             MODULEINFO info;
00331             if( GetModuleInformation( proc, mod[i], &info, sizeof( info ) ) != 0 )
00332             {
00333                 const auto base = uint64_t( info.lpBaseOfDll );
00334                 if( addr >= base && addr < base + info.SizeOfImage )
00335                 {
00336                     char name[1024];
00337                     const auto res = GetModuleFileNameA( mod[i], name, 1021 );
00338                     if( res > 0 )
00339                     {
00340                         // since this is the first time we encounter this module, load its symbols (needed for modules loaded after SymInitialize)
00341                         SymLoadModuleEx(proc, NULL, name, NULL, (DWORD64)info.lpBaseOfDll, info.SizeOfImage, NULL, 0);
00342                         auto ptr = name + res;
00343                         while( ptr > name && *ptr != '\\' && *ptr != '/' ) ptr--;
00344                         if( ptr > name ) ptr++;
00345                         const auto namelen = name + res - ptr;
00346                         auto cache = s_modCache->push_next();
00347                         cache->start = base;
00348                         cache->end = base + info.SizeOfImage;
00349                         cache->name = (char*)tracy_malloc_fast( namelen+3 );
00350                         cache->name[0] = '[';
00351                         memcpy( cache->name+1, ptr, namelen );
00352                         cache->name[namelen+1] = ']';
00353                         cache->name[namelen+2] = '\0';
00354                         return cache->name;
00355                     }
00356                 }
00357             }
00358         }
00359     }
00360     return "[unknown]";
00361 }
