00391 CallstackEntryData DecodeCallstackPtr( uint64_t ptr )
00392 {
00393     int write;
00394     const auto proc = GetCurrentProcess();
00395     InitRpmalloc();
00396 
00397 #ifdef TRACY_DBGHELP_LOCK
00398     DBGHELP_LOCK;
00399 #endif
00400 
00401     const auto moduleName = GetModuleNameAndPrepareSymbols(ptr);
00402 
00403 #if !defined TRACY_NO_CALLSTACK_INLINES
00404     BOOL doInline = FALSE;
00405     DWORD ctx = 0;
00406     DWORD inlineNum = 0;
00407     if( _SymAddrIncludeInlineTrace )
00408     {
00409         inlineNum = _SymAddrIncludeInlineTrace( proc, ptr );
00410         if( inlineNum > MaxCbTrace - 1 ) inlineNum = MaxCbTrace - 1;
00411         DWORD idx;
00412         if( inlineNum != 0 ) doInline = _SymQueryInlineTrace( proc, ptr, 0, ptr, ptr, &ctx, &idx );
00413     }
00414     if( doInline )
00415     {
00416         write = inlineNum;
00417         cb_num = 1 + inlineNum;
00418     }
00419     else
00420 #endif
00421     {
00422         write = 0;
00423         cb_num = 1;
00424     }
00425 
00426     char buf[sizeof( SYMBOL_INFO ) + MaxNameSize];
00427     auto si = (SYMBOL_INFO*)buf;
00428     si->SizeOfStruct = sizeof( SYMBOL_INFO );
00429     si->MaxNameLen = MaxNameSize;
00430 
00431     const auto symValid = SymFromAddr( proc, ptr, nullptr, si ) != 0;
00432 
00433     IMAGEHLP_LINE64 line;
00434     DWORD displacement = 0;
00435     line.SizeOfStruct = sizeof(IMAGEHLP_LINE64);
00436 
00437     {
00438         const char* filename;
00439         const auto res = SymGetLineFromAddr64( proc, ptr, &displacement, &line );
00440         if( res == 0 || line.LineNumber >= 0xF00000 )
00441         {
00442             filename = "[unknown]";
00443             cb_data[write].line = 0;
00444         }
00445         else
00446         {
00447             filename = line.FileName;
00448             cb_data[write].line = line.LineNumber;
00449         }
00450 
00451         cb_data[write].name = symValid ? CopyStringFast( si->Name, si->NameLen ) : CopyStringFast( moduleName );
00452         cb_data[write].file = CopyStringFast( filename );
00453         if( symValid )
00454         {
00455             cb_data[write].symLen = si->Size;
00456             cb_data[write].symAddr = si->Address;
00457         }
00458         else
00459         {
00460             cb_data[write].symLen = 0;
00461             cb_data[write].symAddr = 0;
00462         }
00463     }
00464 
00465 #if !defined TRACY_NO_CALLSTACK_INLINES
00466     if( doInline )
00467     {
00468         for( DWORD i=0; i<inlineNum; i++ )
00469         {
00470             auto& cb = cb_data[i];
00471             const auto symInlineValid = _SymFromInlineContext( proc, ptr, ctx, nullptr, si ) != 0;
00472             const char* filename;
00473             if( _SymGetLineFromInlineContext( proc, ptr, ctx, 0, &displacement, &line ) == 0 )
00474             {
00475                 filename = "[unknown]";
00476                 cb.line = 0;
00477             }
00478             else
00479             {
00480                 filename = line.FileName;
00481                 cb.line = line.LineNumber;
00482             }
00483 
00484             cb.name = symInlineValid ? CopyStringFast( si->Name, si->NameLen ) : CopyStringFast( moduleName );
00485             cb.file = CopyStringFast( filename );
00486             if( symInlineValid )
00487             {
00488                 cb.symLen = si->Size;
00489                 cb.symAddr = si->Address;
00490             }
00491             else
00492             {
00493                 cb.symLen = 0;
00494                 cb.symAddr = 0;
00495             }
00496 
00497             ctx++;
00498         }
00499     }
00500 #endif
00501 #ifdef TRACY_DBGHELP_LOCK
00502     DBGHELP_UNLOCK;
00503 #endif
00504 
00505     return { cb_data, uint8_t( cb_num ), moduleName };
00506 }
