00541 
00542 static void InitKernelSymbols()
00543 {
00544     FILE* f = fopen( "/proc/kallsyms", "rb" );
00545     if( !f ) return;
00546     tracy::FastVector<KernelSymbol> tmpSym( 1024 );
00547     size_t linelen = 16 * 1024;     // linelen must be big enough to prevent reallocs in getline()
00548     auto linebuf = (char*)tracy_malloc( linelen );
00549     ssize_t sz;
00550     while( ( sz = getline( &linebuf, &linelen, f ) ) != -1 )
00551     {
00552         auto ptr = linebuf;
00553         uint64_t addr = 0;
00554         while( *ptr != ' ' )
00555         {
00556             auto v = *ptr;
00557             if( v >= '0' && v <= '9' )
00558             {
00559                 v -= '0';
00560             }
00561             else if( v >= 'a' && v <= 'f' )
00562             {
00563                 v -= 'a';
00564                 v += 10;
00565             }
00566             else if( v >= 'A' && v <= 'F' )
00567             {
00568                 v -= 'A';
00569                 v += 10;
00570             }
00571             else
00572             {
00573                 assert( false );
00574             }
00575             assert( ( v & ~0xF ) == 0 );
00576             addr <<= 4;
00577             addr |= v;
00578             ptr++;
00579         }
00580         if( addr == 0 ) continue;
00581         ptr++;
00582         if( *ptr != 'T' && *ptr != 't' ) continue;
00583         ptr += 2;
00584         const auto namestart = ptr;
00585         while( *ptr != '\t' && *ptr != '\n' ) ptr++;
00586         const auto nameend = ptr;
00587         const char* modstart = nullptr;
00588         const char* modend;
00589         if( *ptr == '\t' )
00590         {
00591             ptr += 2;
00592             modstart = ptr;
00593             while( *ptr != ']' ) ptr++;
00594             modend = ptr;
00595         }
00596 
00597         auto strname = (char*)tracy_malloc_fast( nameend - namestart + 1 );
00598         memcpy( strname, namestart, nameend - namestart );
00599         strname[nameend-namestart] = '\0';
00600 
00601         char* strmod = nullptr;
00602         if( modstart )
00603         {
00604             strmod = (char*)tracy_malloc_fast( modend - modstart + 1 );
00605             memcpy( strmod, modstart, modend - modstart );
00606             strmod[modend-modstart] = '\0';
00607         }
00608 
00609         auto sym = tmpSym.push_next();
00610         sym->addr = addr;
00611         sym->name = strname;
00612         sym->mod = strmod;
00613     }
00614     tracy_free_fast( linebuf );
00615     fclose( f );
00616     if( tmpSym.empty() ) return;
00617 
00618     std::sort( tmpSym.begin(), tmpSym.end(), []( const KernelSymbol& lhs, const KernelSymbol& rhs ) { return lhs.addr > rhs.addr; } );
00619     s_kernelSymCnt = tmpSym.size();
00620     s_kernelSym = (KernelSymbol*)tracy_malloc_fast( sizeof( KernelSymbol ) * s_kernelSymCnt );
00621     memcpy( s_kernelSym, tmpSym.data(), sizeof( KernelSymbol ) * s_kernelSymCnt );
00622     TracyDebug( "Loaded %zu kernel symbols\n", s_kernelSymCnt );
00623 }
00624 #endif
00625 
00626 char* NormalizePath( const char* path )
00627 {
00628     if( path[0] != '/' ) return nullptr;
00629 
00630     const char* ptr = path;
00631     const char* end = path;
00632     while( *end ) end++;
00633 
00634     char* res = (char*)tracy_malloc( end - ptr + 1 );
00635     size_t rsz = 0;
00636 
00637     while( ptr < end )
00638     {
00639         const char* next = ptr;
00640         while( next < end && *next != '/' ) next++;
00641         size_t lsz = next - ptr;
00642         switch( lsz )
00643         {
00644         case 2:
00645             if( memcmp( ptr, "..", 2 ) == 0 )
00646             {
00647                 const char* back = res + rsz - 1;
00648                 while( back > res && *back != '/' ) back--;
00649                 rsz = back - res;
00650                 ptr = next + 1;
00651                 continue;
00652             }
00653             break;
00654         case 1:
00655             if( *ptr == '.' )
00656             {
00657                 ptr = next + 1;
00658                 continue;
00659             }
00660             break;
00661         case 0:
00662             ptr = next + 1;
00663             continue;
00664         }
00665         if( rsz != 1 ) res[rsz++] = '/';
00666         memcpy( res+rsz, ptr, lsz );
00667         rsz += lsz;
00668         ptr = next + 1;
00669     }
00670 
00671     if( rsz == 0 )
00672     {
00673         memcpy( res, "/", 2 );
00674     }
00675     else
00676     {
00677         res[rsz] = '\0';
00678     }
00679     return res;
00680 }
