00725 int GetDebugInfoDescriptor( const char* buildid_data, size_t buildid_size, const char* filename )
00726 {
00727     auto buildid = (uint8_t*)buildid_data;
00728     auto it = FindDebugInfo( s_di_known, buildid, buildid_size );
00729     if( it ) return it->fd >= 0 ? dup( it->fd ) : -1;
00730 
00731     int fd = debuginfod_find_debuginfo( s_debuginfod, buildid, buildid_size, nullptr );
00732     it = s_di_known.push_next();
00733     it->buildid_size = buildid_size;
00734     it->buildid = (uint8_t*)tracy_malloc( buildid_size );
00735     memcpy( it->buildid, buildid, buildid_size );
00736     const auto fnsz = strlen( filename ) + 1;
00737     it->filename = (char*)tracy_malloc( fnsz );
00738     memcpy( it->filename, filename, fnsz );
00739     it->fd = fd >= 0 ? fd : -1;
00740     TracyDebug( "DebugInfo descriptor query: %i, fn: %s\n", fd, filename );
00741     return it->fd;
00742 }
