00796 static int SymbolAddressDataCb( void* data, uintptr_t pc, uintptr_t lowaddr, const char* fn, int lineno, const char* function )
00797 {
00798     auto& sym = *(CallstackSymbolData*)data;
00799     if( !fn )
00800     {
00801         sym.file = "[unknown]";
00802         sym.line = 0;
00803         sym.needFree = false;
00804     }
00805     else
00806     {
00807         sym.file = NormalizePath( fn );
00808         if( !sym.file ) sym.file = CopyString( fn );
00809         sym.line = lineno;
00810         sym.needFree = true;
00811     }
00812 
00813     return 1;
00814 }
00815 
00816 static void SymbolAddressErrorCb( void* data, const char* /*msg*/, int /*errnum*/ )
00817 {
00818     auto& sym = *(CallstackSymbolData*)data;
00819     sym.file = "[unknown]";
00820     sym.line = 0;
00821     sym.needFree = false;
00822 }
00823 
00824 CallstackSymbolData DecodeSymbolAddress( uint64_t ptr )
00825 {
00826     CallstackSymbolData sym;
00827     backtrace_pcinfo( cb_bts, ptr, SymbolAddressDataCb, SymbolAddressErrorCb, &sym );
00828     return sym;
00829 }
00830 
00831 static int CallstackDataCb( void* /*data*/, uintptr_t pc, uintptr_t lowaddr, const char* fn, int lineno, const char* function )
00832 {
00833     cb_data[cb_num].symLen = 0;
00834     cb_data[cb_num].symAddr = (uint64_t)lowaddr;
00835 
00836     if( !fn && !function )
00837     {
00838         const char* symname = nullptr;
00839         auto vptr = (void*)pc;
00840         ptrdiff_t symoff = 0;
00841 
00842         Dl_info dlinfo;
00843         if( dladdr( vptr, &dlinfo ) )
00844         {
00845             symname = dlinfo.dli_sname;
00846             symoff = (char*)pc - (char*)dlinfo.dli_saddr;
00847             const char* demangled = ___tracy_demangle( symname );
00848             if( demangled ) symname = demangled;
00849         }
00850 
00851         if( !symname ) symname = "[unknown]";
00852 
00853         if( symoff == 0 )
00854         {
00855             const auto len = std::min<size_t>( strlen( symname ), std::numeric_limits<uint16_t>::max() );
00856             cb_data[cb_num].name = CopyStringFast( symname, len );
00857         }
00858         else
00859         {
00860             char buf[32];
00861             const auto offlen = sprintf( buf, " + %td", symoff );
00862             const auto namelen = std::min<size_t>( strlen( symname ), std::numeric_limits<uint16_t>::max() - offlen );
00863             auto name = (char*)tracy_malloc_fast( namelen + offlen + 1 );
00864             memcpy( name, symname, namelen );
00865             memcpy( name + namelen, buf, offlen );
00866             name[namelen + offlen] = '\0';
00867             cb_data[cb_num].name = name;
00868         }
00869 
00870         cb_data[cb_num].file = CopyStringFast( "[unknown]" );
00871         cb_data[cb_num].line = 0;
00872     }
00873     else
00874     {
00875         if( !fn ) fn = "[unknown]";
00876         if( !function )
00877         {
00878             function = "[unknown]";
00879         }
00880         else
00881         {
00882             const char* demangled = ___tracy_demangle( function );
00883             if( demangled ) function = demangled;
00884         }
00885 
00886         const auto len = std::min<size_t>( strlen( function ), std::numeric_limits<uint16_t>::max() );
00887         cb_data[cb_num].name = CopyStringFast( function, len );
00888         cb_data[cb_num].file = NormalizePath( fn );
00889         if( !cb_data[cb_num].file ) cb_data[cb_num].file = CopyStringFast( fn );
00890         cb_data[cb_num].line = lineno;
00891     }
00892 
00893     if( ++cb_num >= MaxCbTrace )
00894     {
00895         return 1;
00896     }
00897     else
00898     {
00899         return 0;
00900     }
00901 }
00902 
00903 static void CallstackErrorCb( void* /*data*/, const char* /*msg*/, int /*errnum*/ )
00904 {
00905     for( int i=0; i<cb_num; i++ )
00906     {
00907         tracy_free_fast( (void*)cb_data[i].name );
00908         tracy_free_fast( (void*)cb_data[i].file );
00909     }
00910 
00911     cb_data[0].name = CopyStringFast( "[error]" );
00912     cb_data[0].file = CopyStringFast( "[error]" );
00913     cb_data[0].line = 0;
00914 
00915     cb_num = 1;
00916 }
00917 
00918 void SymInfoCallback( void* /*data*/, uintptr_t pc, const char* symname, uintptr_t symval, uintptr_t symsize )
00919 {
00920     cb_data[cb_num-1].symLen = (uint32_t)symsize;
00921     cb_data[cb_num-1].symAddr = (uint64_t)symval;
00922 }
00923 
00924 void SymInfoError( void* /*data*/, const char* /*msg*/, int /*errnum*/ )
00925 {
00926     cb_data[cb_num-1].symLen = 0;
00927     cb_data[cb_num-1].symAddr = 0;
00928 }
