00930 CallstackEntryData DecodeCallstackPtr( uint64_t ptr )
00931 {
00932     InitRpmalloc();
00933     if( ptr >> 63 == 0 )
00934     {
00935         cb_num = 0;
00936         backtrace_pcinfo( cb_bts, ptr, CallstackDataCb, CallstackErrorCb, nullptr );
00937         assert( cb_num > 0 );
00938 
00939         backtrace_syminfo( cb_bts, ptr, SymInfoCallback, SymInfoError, nullptr );
00940 
00941         const char* symloc = nullptr;
00942         Dl_info dlinfo;
00943         if( dladdr( (void*)ptr, &dlinfo ) ) symloc = dlinfo.dli_fname;
00944 
00945         return { cb_data, uint8_t( cb_num ), symloc ? symloc : "[unknown]" };
00946     }
00947 #ifdef __linux
00948     else if( s_kernelSym )
00949     {
00950         auto it = std::lower_bound( s_kernelSym, s_kernelSym + s_kernelSymCnt, ptr, []( const KernelSymbol& lhs, const uint64_t& rhs ) { return lhs.addr > rhs; } );
00951         if( it != s_kernelSym + s_kernelSymCnt )
00952         {
00953             cb_data[0].name = CopyStringFast( it->name );
00954             cb_data[0].file = CopyStringFast( "<kernel>" );
00955             cb_data[0].line = 0;
00956             cb_data[0].symLen = 0;
00957             cb_data[0].symAddr = it->addr;
00958             return { cb_data, 1, it->mod ? it->mod : "<kernel>" };
00959         }
00960     }
00961 #endif
00962 
00963     cb_data[0].name = CopyStringFast( "[unknown]" );
00964     cb_data[0].file = CopyStringFast( "<kernel>" );
00965     cb_data[0].line = 0;
00966     cb_data[0].symLen = 0;
00967     cb_data[0].symAddr = 0;
00968     return { cb_data, 1, "<kernel>" };
00969 }
